WITH filtered AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, SUBSTRING(txn_type, 1, 4) AS txn_type_prefix FROM transactions WHERE amount <= 1900) SELECT *, DENSE_RANK() OVER (PARTITION BY merchant ORDER BY amount) AS amount_dense_rank, SUM(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount FROM filtered;
